Let $\Sigma$ be a proper nonempty subset of $ {\rm Int} (2{\mat{\mu}} + \mat{\lambda} + \mat{1/2}) = {\rm Int} (2{\mat{\mu}}) $. We set

\begin{align*}
V(\mat{\mu}, \mat{\lambda}, \Sigma) &=& &\left( \bigcap_{i\in \Sigma}V_i^+(\mat{\mu}, \mat{\lambda})\right)/\sum_{j\in {\rm Int} (2{\mat{\mu}})\setminus\Sigma}\left( \bigcap_{k \in \Sigma \cup \{ j\}}V_k^+(\mat{\mu}, \mat{\lambda}) \right),\\
V(\mat{\mu}, \mat{\lambda}, \emptyset) &=& &V(\mat{\mu}, \mat{\lambda})/\Big(\sum\limits_{j\in{\rm Int} (2{\mat{\mu}})}V_j^{+}(\mat{\mu}, \mat{\lambda})\Big),\\
V(\mat{\mu}, \mat{\lambda}, {\rm Int} (2{\mat{\mu}})) &=& &\bigcap\limits_{i\in {\rm Int} (2{\mat{\mu}})}V_i^{+}(\mat{\mu}, \mat{\lambda}).
\end{align*}
